/** Complete immutable captured bytes and source-record/native-format consistency. No producer-host access. */
final class CrossmapBundle {
    private CrossmapBundle() { }
    static Pin producer()throws IOException {
        try{Path p=Path.of(CrossmapBundle.class.getProtectionDomain().getCodeSource().getLocation().toURI()).toAbsolutePath().normalize();if(!Files.isRegularFile(p))throw new IOException("Run conversion and verification through the exact packaged executable JAR");return pin(p,1000000000L,()->{});}catch(java.net.URISyntaxException e){throw new IOException(e);}
    }
    static Map<String,Object> files(Path root,CrossmapRequest.Spec s,Runnable check)throws IOException {
        var result=new TreeMap<String,Object>();long generated=0;
        for(var row:tree(root,s.process().fileCount(),s.process().workspaceBytes(),Math.max(s.inputBytes(),s.outputBytes())+16777216,check).entrySet()){
            require(row.getValue().kind().equals("file"),"Captured conversion cannot contain symbolic links");
            if(!s.originals().containsKey(row.getKey())){
                generated=Math.addExact(generated,row.getValue().pin().bytes());
                require(generated<=Math.addExact(s.outputBytes(),16777216),"Complete generated outputs/evidence exceed aggregate output capacity plus16MiB metadata reserve");
            }
            result.put(row.getKey(),Map.of("bytes",row.getValue().pin().bytes(),"sha256",row.getValue().pin().sha256()));
        }
        return result;
    }
    static void verify(Path supplied,boolean precommit,Runnable check)throws IOException {
        Path root=supplied.toAbsolutePath().normalize();directory(root);require(!Files.exists(root.resolve("FAILURE.json"))&&!Files.exists(root.resolve("BRIDGE-FAILURE.json")),"Failed source/captured result is not admitted");require(Files.exists(root.resolve("INCOMPLETE.json"))==precommit,"Captured result is incomplete or has a wrong commit guard");var done=object(json(root.resolve("COMPLETED.json"),1048576));keys(done,"schema_version","status","manifest","conversion_admitted");integer(done.get("schema_version"),1,1);require("COMPLETE_ORIGINAL_CROSSMAP_CONVERSION".equals(done.get("status"))&&Boolean.TRUE.equals(done.get("conversion_admitted")),"Missing overall conversion admission");Pin manifest=pin(root.resolve("manifest.json"),16777216,check);require(manifest.equals(fingerprint(done.get("manifest"),16777216)),"Captured manifest changed");var saved=object(json(root.resolve("manifest.json"),16777216));keys(saved,"schema_version","profile","status","files","producer","conversion_admitted","whole_paper_reproduced");integer(saved.get("schema_version"),1,1);require("crossmap-original-source-conversion-v1".equals(saved.get("profile"))&&"COMPLETE_ORIGINAL_CROSSMAP_CAPTURED_CONTRACT".equals(saved.get("status"))&&Boolean.TRUE.equals(saved.get("conversion_admitted"))&&Boolean.FALSE.equals(saved.get("whole_paper_reproduced")),"Expanded/different result profile");require(producer().equals(fingerprint(saved.get("producer"),1000000000L)),"Restore the exact producing executable JAR; do not refresh historical expected hashes");
        CrossmapRequest.Spec s;try{s=CrossmapRequest.read(root.resolve("request.json"),false);}catch(CrossmapRuntime.Unavailable e){throw new IOException("Captured source contract differs; no live runtime was consulted",e);}
        inventory(root,s,saved.get("files"),precommit,check);audit(root,s,check);require(Files.readString(root.resolve("WARNINGS.md"),StandardCharsets.UTF_8).equals(CrossmapWorkflow.warnings(root,s)),"Warnings/required actions changed");inventory(root,s,saved.get("files"),precommit,check);require(manifest.equals(pin(root.resolve("manifest.json"),16777216,check)),"Manifest changed during complete readback");
    }
    private static void inventory(Path root,CrossmapRequest.Spec s,Object declared,boolean precommit,Runnable check)throws IOException {
        var actual=files(root,s,check);var names=new HashSet<>(Set.of("request.json","source-inputs.json","support/source-lock.json","support/analysis.py","runtime/marker.json","runtime/setup-completed.json","runtime/health-completed.json","runtime/provenance.json","process/launch.json","process/WARNINGS.md","process/process.stdout","process/process.stderr","process/process.json","audit/original-command.json","audit/original.stdout","audit/original.stderr","audit/original-process.json","OUTPUT-LEDGER.jsonl","OUTPUT-AUDIT.json","WARNINGS.md","manifest.json","COMPLETED.json"));names.addAll(s.originals().keySet());
        if(s.format().equals("bigwig"))names.addAll(Set.of("outputs/mapped.bw","outputs/mapped.sorted.bgr","audit/source-mapped.bgr","audit/source-expected.sorted.bgr","BINARY-OUTPUT.json"));else{names.add(s.outputMember());names.add(s.outputMember()+".unmap");}if(s.format().equals("vcf"))names.add("inputs/reference.fa.fai");if(precommit)names.add("INCOMPLETE.json");var missing=new TreeSet<>(names);missing.removeAll(actual.keySet());var extra=new TreeSet<>(actual.keySet());extra.removeAll(names);require(missing.isEmpty()&&extra.isEmpty(),"Complete conversion namespace differs; missing="+missing+"; extra="+extra);
        var directories=new HashSet<String>();directories.add("");for(String n:names){Path p=Path.of(n).getParent();while(p!=null){directories.add(p.toString().replace('\\','/'));p=p.getParent();}}try(var paths=Files.walk(root)){for(Path p:paths.toList())if(Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS))require(directories.remove(root.relativize(p).toString().replace('\\','/')),"Extra/duplicate captured directory");}require(directories.isEmpty(),"Captured directories missing");
        actual.remove("manifest.json");actual.remove("COMPLETED.json");actual.remove("INCOMPLETE.json");require(NextflowJson.json(actual).equals(NextflowJson.json(declared)),"Complete captured file bytes changed");
    }
    static void audit(Path root,CrossmapRequest.Spec s,Runnable check)throws IOException {
        check.run();require(pin(root.resolve("support/source-lock.json"),1048576,check).equals(CrossmapRuntime.bytesPin(CrossmapRuntime.resource("source-lock.json")))&&pin(root.resolve("support/analysis.py"),1048576,check).equals(CrossmapRuntime.bytesPin(CrossmapRuntime.resource("analysis.py"))),"Captured execution support differs from producer");
        var source=object(json(root.resolve("source-inputs.json"),1048576));keys(source,"files","complete_original_bytes","source_bytes_unchanged");var originals=object(source.get("files"));require(originals.keySet().equals(s.originals().keySet())&&Boolean.TRUE.equals(source.get("source_bytes_unchanged")),"Complete original capture differs");long bytes=0;for(var row:s.originals().entrySet()){var info=object(originals.get(row.getKey()));keys(info,"original","pin");require(row.getValue().equals(info.get("original")),"Original path declaration changed");Pin value=pin(root.resolve(row.getKey()),s.inputBytes(),check);require(value.equals(fingerprint(info.get("pin"),s.inputBytes())),"Captured original bytes changed: "+row.getKey());bytes=Math.addExact(bytes,value.bytes());}require(bytes<=s.inputBytes()&&bytes==integer(source.get("complete_original_bytes"),0,s.inputBytes()),"Complete original byte population differs");
        var process=object(json(root.resolve("process/process.json"),16777216));require("completed-process-only".equals(process.get("status"))&&integer(process.get("exit_code"),0,0)==0&&list(process.get("owned_live_after_cleanup")).isEmpty(),"Original/audit process is not terminal and clean");require(NextflowJson.json(s.process()).equals(NextflowJson.json(process.get("limits"))),"Captured process capacities differ");var original=object(json(root.resolve("audit/original-process.json"),1048576));require(integer(original.get("exit_code"),0,0)==0&&s.edition().equals(original.get("source_version"))&&Boolean.FALSE.equals(original.get("original_source_modified")),"Original conversion did not complete with the selected source edition");
        runtimeEvidence(root,check);var summary=object(json(root.resolve("OUTPUT-AUDIT.json"),1048576));require("COMPLETE_ORIGINAL_SOURCE_OUTPUT_CONSISTENCY".equals(summary.get("status"))&&s.edition().equals(summary.get("edition"))&&s.format().equals(summary.get("format"))&&s.unmappedPolicy().equals(summary.get("unmapped_policy")),"Source/output consistency scope differs");for(String field:List.of("original_source_modified","author_edition_inferred","author_Python37_reproduced","whole_paper_reproduced","independent_source_model_reimplementation"))require(Boolean.FALSE.equals(summary.get(field)),"Expanded source/result claim: "+field);
        var counts=object(summary.get("counts"));var computed=new TreeMap<String,Long>();for(String field:List.of("source_records","mapped_inputs","rejected_inputs","partially_mapped_inputs","inputs_with_multiple_output_blocks","bed20_metadata_omissions","mapped_records","rejected_records","ledger_records"))computed.put(field,0L);
        var expected=new HashMap<String,Long>();var rejected=new HashMap<String,Long>();var signalInput=new HashMap<String,Long>();var signalTargets=new HashMap<String,Long>();BigWigSignal.Data inputSignal=null;
        if(s.format().equals("bigwig")){inputSignal=BigWigSignal.read(root.resolve(s.inputMember()),s.inputBytes(),s.records(),s.blockBytes());for(var seg:inputSignal.segments())increment(signalInput,signalKey(seg.chromosome(),seg.start(),seg.end(),seg.value()),s.records());}
        Lines input=s.format().equals("bigwig")?null:new Lines(root.resolve(s.inputMember()),s.inputEncoding().equals("gzip"),s.inputBytes());
        try(var ledger=new Lines(root.resolve("OUTPUT-LEDGER.jsonl"),false,s.outputBytes());input){String line;long index=0;
            while((line=ledger.next())!=null){check.run();require(index<s.records(),"Complete record ledger exceeds capacity");var row=object(SimpleJson.parse(line));require(integer(row.get("index"),0,s.records())==index,"Skipped/duplicate ledger index");index++;increase(computed,"ledger_records");String kind=text(row.get("kind"));int sourceFields=0;String logicalInput=null;List<Object> sourceInterval=null;
                if(input!=null){String raw=input.next();require(raw!=null,"Ledger exceeds complete input");String clean=logical(raw);logicalInput=clean;require(sha(clean.getBytes(StandardCharsets.UTF_8)).equals(row.get("input_sha256")),"Logical source record/witness mismatch");boolean ignored=clean.isEmpty()||clean.startsWith("#")||s.format().equals("bed")&&(clean.startsWith("track")||clean.startsWith("browser"));require(kind.equals(ignored?"ignored":"data"),"Source record classification differs");if(ignored){require(list(row.get("mapped_hashes")).isEmpty()&&list(row.get("rejected_hashes")).isEmpty(),"Ignored source line emitted records");continue;}if(s.format().equals("bed")){sourceFields=clean.split("[\\p{javaWhitespace}\\p{Z}\\u0085]+").length;require(integer(row.get("source_fields"),0,Integer.MAX_VALUE)==sourceFields,"BED source column population differs");}}
                else{require(kind.equals("signal"),"Unknown signal witness kind");var src=interval(row.get("source_interval"));sourceInterval=src;String key=signalKey(text(src.get(0)),(long)src.get(1),(long)src.get(2),(double)src.get(3));require(key.equals(row.get("input_sha256")),"Signal witness key differs");decrement(signalInput,key);}
                increase(computed,"source_records");boolean mapped;
                if(input==null){mapped="mapped".equals(row.get("source_disposition"));require(mapped||"discarded-no-single-mapped-block".equals(row.get("source_disposition")),"Unknown source signal disposition");if(mapped){var target=interval(row.get("target_interval"));require(Double.doubleToRawLongBits((double)target.get(3))==Double.doubleToRawLongBits((double)sourceInterval.get(3)),"Original single-block signal value was changed");increment(signalTargets,signalKey(text(target.get(0)),(long)target.get(1),(long)target.get(2),(double)target.get(3)),s.records());}}
                else{var good=list(row.get("mapped_hashes"));var bad=list(row.get("rejected_hashes"));require(!good.isEmpty()^!bad.isEmpty(),"Each source row requires one complete mapped/rejected disposition");if(s.format().equals("vcf"))require(good.size()+bad.size()==1,"VCF source row emitted multiple outcomes");mapped=!good.isEmpty();for(Object hash:good)increment(expected,hashText(hash),s.records());for(Object hash:bad)increment(rejected,hashText(hash),s.records());if(good.size()>1)increase(computed,"inputs_with_multiple_output_blocks");if(s.format().equals("bed")&&sourceFields==20&&mapped)increase(computed,"bed20_metadata_omissions");}
                increase(computed,mapped?"mapped_inputs":"rejected_inputs");if(mapped){long span=integer(row.get("source_span_bases"),0,Long.MAX_VALUE),covered=integer(row.get("source_covered_bases"),0,span),nativeSpan;if(sourceInterval!=null)nativeSpan=(long)sourceInterval.get(2)-(long)sourceInterval.get(1);else{String[] fields=logicalInput.split("[\\p{javaWhitespace}\\p{Z}\\u0085]+");if(s.format().equals("vcf"))nativeSpan=fields[3].codePointCount(0,fields[3].length());else if(fields.length<12)nativeSpan=Math.subtractExact(Long.parseLong(fields[2]),Long.parseLong(fields[1]));else{nativeSpan=0;for(String value:fields[10].replaceAll(",+$","").split(","))nativeSpan=Math.addExact(nativeSpan,Long.parseLong(value));}}require(span==nativeSpan,"Complete source span/exon-base population differs");if(covered<span)increase(computed,"partially_mapped_inputs");}
            }
            if(input!=null)require(input.next()==null,"Input exceeds complete record ledger");else require(signalInput.isEmpty(),"Raw input signal intervals are absent from ledger");
        }
        if(s.format().equals("bigwig")){var witnesses=graph(root.resolve("audit/source-mapped.bgr"),s,false);require(witnesses.equals(signalTargets),"Complete source signal targets differ from per-input ledger");require(pin(root.resolve("audit/source-expected.sorted.bgr"),s.outputBytes(),check).equals(pin(root.resolve("outputs/mapped.sorted.bgr"),s.outputBytes(),check)),"Complete original signal merge differs");var data=BigWigSignal.read(root.resolve("outputs/mapped.bw"),s.outputBytes(),s.records(),s.blockBytes());var actual=new HashMap<String,Long>();for(var seg:data.segments())increment(actual,signalKey(seg.chromosome(),seg.start(),seg.end(),seg.value()),s.records());require(actual.equals(graph(root.resolve("outputs/mapped.sorted.bgr"),s,true)),"Every raw native BigWig interval must equal float32 bedGraph values");computed.put("mapped_records",(long)data.segments().size());binarySummary(root,data);}
        else{computed.put("mapped_records",compareRows(root.resolve(s.outputMember()),expected,s));computed.put("rejected_records",compareRows(root.resolve(s.outputMember()+".unmap"),rejected,s));if(s.format().equals("vcf"))reference(root,s,check);}
        require(counts.keySet().equals(computed.keySet()),"Missing/extra source count populations");for(var row:computed.entrySet())require(integer(counts.get(row.getKey()),0,s.records())==row.getValue(),"Complete source population differs: "+row.getKey());require(computed.get("source_records")==computed.get("mapped_inputs")+computed.get("rejected_inputs"),"Input dispositions are incomplete");require(s.unmappedPolicy().equals("retain")||computed.get("rejected_inputs")==0&&computed.get("partially_mapped_inputs")==0,"Explicit source-loss policy was not enforced");
    }
    private static void runtimeEvidence(Path root,Runnable check)throws IOException {
        var marker=object(json(root.resolve("runtime/marker.json"),4194304));var completed=object(json(root.resolve("runtime/setup-completed.json"),1048576));var health=object(json(root.resolve("runtime/health-completed.json"),1048576));var saved=object(json(root.resolve("runtime/provenance.json"),1048576));String profile=text(object(SimpleJson.parse(utf8(CrossmapRuntime.resource("source-lock.json")))).get("profile"));var helpers=object(saved.get("execution_helpers"));require(helpers.keySet().equals(Set.of("/usr/bin/setsid","/usr/bin/prlimit")),"Missing/extra captured Linux execution helpers");for(Object value:helpers.values())fingerprint(value,16777216);require(profile.equals(marker.get("profile"))&&profile.equals(completed.get("profile"))&&profile.equals(saved.get("profile")),"Captured runtime profile differs");Pin actual=pin(root.resolve("runtime/marker.json"),4194304,check);require(actual.equals(fingerprint(completed.get("runtime_marker"),4194304))&&actual.equals(fingerprint(saved.get("marker"),4194304)),"Captured runtime marker/setup proof differs");require(fingerprint(marker.get("source_lock"),1048576).equals(CrossmapRuntime.bytesPin(CrossmapRuntime.resource("source-lock.json"))),"Captured original source lock differs");require(pin(root.resolve("runtime/setup-completed.json"),1048576,check).equals(fingerprint(saved.get("setup_report"),1048576))&&pin(root.resolve("runtime/health-completed.json"),1048576,check).equals(fingerprint(saved.get("synthetic_health"),1048576)),"Captured synthetic health differs");require("PASS_BOTH_ORIGINAL_EDITIONS_THREE_FORMATS".equals(health.get("status"))&&list(health.get("cases")).size()==6&&Boolean.FALSE.equals(saved.get("author_Python37_reproduced")),"Expanded/incomplete runtime qualification");
    }
    private static void increase(Map<String,Long> map,String name){map.put(name,map.get(name)+1);}
    private static String hashText(Object raw)throws IOException{String s=text(raw);require(s.matches("[0-9a-f]{64}"),"Invalid record SHA256");return s;}
    private static void increment(Map<String,Long> map,String value,int capacity)throws IOException{map.merge(value,1L,Long::sum);require(map.size()<=capacity,"Complete record population exceeds capacity");}
    private static void decrement(Map<String,Long> map,String value)throws IOException{Long n=map.get(value);require(n!=null&&n>0,"Output/source record absent or duplicated");if(n==1)map.remove(value);else map.put(value,n-1);}
    private static long compareRows(Path path,Map<String,Long> expected,CrossmapRequest.Spec s)throws IOException{long count=0;try(var lines=new Lines(path,false,s.outputBytes())){String line;while((line=lines.next())!=null){line=logical(line);if(line.isEmpty()||line.startsWith("#"))continue;require(++count<=s.records(),"Complete output records exceed capacity");decrement(expected,sha(line.getBytes(StandardCharsets.UTF_8)));}}require(expected.isEmpty(),"Expected source-output records missing");return count;}
    private static List<Object> interval(Object value)throws IOException{var raw=list(value);require(raw.size()==4,"Signal interval requires four fields");String chr=text(raw.get(0));long start=integer(raw.get(1),0,Long.MAX_VALUE),end=integer(raw.get(2),start+1,Long.MAX_VALUE);if(!(raw.get(3)instanceof Number n)||!Double.isFinite(n.doubleValue()))throw new IOException("Nonfinite/invalid signal witness");return List.of(chr,start,end,n.doubleValue());}
    private static String signalKey(String chromosome,long start,long end,double value)throws IOException{require(Double.isFinite(value)&&Float.isFinite((float)value),"Signal exceeds finite float32 storage");byte[] name=chromosome.getBytes(StandardCharsets.UTF_8);var b=ByteBuffer.allocate(name.length+1+20).order(ByteOrder.LITTLE_ENDIAN);b.put(name).put((byte)0).putLong(start).putLong(end).putFloat((float)value);return sha(b.array());}
    private static Map<String,Long> graph(Path path,CrossmapRequest.Spec s,boolean float32)throws IOException{var result=new HashMap<String,Long>();long count=0;try(var lines=new Lines(path,false,s.outputBytes())){String line;while((line=lines.next())!=null){String[] f=logical(line).split("\\s+");require(f.length==4,"Invalid complete signal witness/bedGraph");long start=Long.parseLong(f[1]),end=Long.parseLong(f[2]);double value=Double.parseDouble(f[3]);require(start>=0&&end>start&&Double.isFinite(value),"Invalid signal geometry/value");require(++count<=s.records(),"Complete signal graph exceeds capacity");increment(result,signalKey(f[0],start,end,value),s.records());}}return result;}
    private static void binarySummary(Path root,BigWigSignal.Data data)throws IOException{var saved=object(json(root.resolve("BINARY-OUTPUT.json"),1048576));BigInteger modulus=BigInteger.ONE.shiftLeft(256),dict=BigInteger.ZERO,rows=BigInteger.ZERO;for(var row:data.dictionary().entrySet()){byte[] name=row.getKey().getBytes(StandardCharsets.UTF_8);var b=ByteBuffer.allocate(name.length+9).order(ByteOrder.LITTLE_ENDIAN).put(name).put((byte)0).putLong(row.getValue());dict=dict.add(new BigInteger(sha(b.array()),16)).mod(modulus);}for(var row:data.segments())rows=rows.add(new BigInteger(signalKey(row.chromosome(),row.start(),row.end(),row.value()),16)).mod(modulus);require(integer(saved.get("dictionary_records"),0,100000)==data.dictionary().size()&&integer(saved.get("interval_records"),0,10000000)==data.segments().size()&&String.format("%064x",dict).equals(saved.get("dictionary_sha256_sum_mod_2_256"))&&String.format("%064x",rows).equals(saved.get("intervals_sha256_sum_mod_2_256"))&&Boolean.TRUE.equals(saved.get("all_raw_intervals_checked"))&&Boolean.FALSE.equals(saved.get("source_zoom_summaries_used")),"Complete independent native binary summary differs");}
    private static void reference(Path root,CrossmapRequest.Spec s,Runnable check)throws IOException {
        Path fasta=root.resolve(s.fastaMember());var expected=FastaSequenceIndexCreator.buildFromFasta(fasta);var actual=new FastaSequenceIndex(Path.of(fasta+".fai"));var a=actual.iterator();for(var entry:expected){require(a.hasNext()&&entry.equals(a.next()),"Complete original generated FAI differs from independent native recomputation");}require(!a.hasNext(),"Extra reference index contigs");
        String[] inputHeader=header(root.resolve(s.inputMember()),s.inputEncoding().equals("gzip"),s.inputBytes()),outputHeader=header(root.resolve(s.outputMember()),false,s.outputBytes());require(Arrays.equals(inputHeader,outputHeader),"VCF column/sample header changed");
        var references=new HashMap<String,String>();try(var ledger=new Lines(root.resolve("OUTPUT-LEDGER.jsonl"),false,s.outputBytes())){String line;while((line=ledger.next())!=null){var row=object(SimpleJson.parse(line));if("data".equals(row.get("kind"))&&!list(row.get("mapped_hashes")).isEmpty()){String key=hashText(list(row.get("mapped_hashes")).get(0)),contig=text(row.get("reference_contig"));String previous=references.putIfAbsent(key,contig);require(previous==null||previous.equals(contig),"Ambiguous source reference-contig witnesses");}}}
        try(var ref=new IndexedFastaSequenceFile(fasta);var values=new Lines(root.resolve(s.outputMember()),false,s.outputBytes())){String line;while((line=values.next())!=null){check.run();line=logical(line);if(line.isEmpty()||line.startsWith("#"))continue;String[] f=line.split("\\t",-1);require(f.length==inputHeader.length&&f.length>=8,"Complete VCF sample/field count differs");long pos=Long.parseLong(f[1]);String contig=references.get(sha(line.getBytes(StandardCharsets.UTF_8)));require(contig!=null&&pos>=1&&!f[3].isEmpty(),"Missing source reference witness/coordinate");String bases=ref.getSubsequenceAt(contig,pos,Math.addExact(pos,f[3].length()-1L)).getBaseString().toUpperCase(Locale.ROOT);require(bases.equals(f[3]),"Mapped REF differs from complete captured target FASTA");}}
    }
    private static String[] header(Path path,boolean gzip,long maximum)throws IOException{String[] result=null;try(var lines=new Lines(path,gzip,maximum)){String s;while((s=lines.next())!=null)if(logical(s).startsWith("#CHROM")){require(result==null,"Duplicate VCF column header");result=logical(s).split("\\t",-1);}}require(result!=null,"Missing complete VCF column header");return result;}
    private static boolean whitespace(char c){return Character.isWhitespace(c)||Character.isSpaceChar(c)||c==0x85;}
    private static String logical(String s){int a=0,b=s.length();while(a<b&&whitespace(s.charAt(a)))a++;while(b>a&&whitespace(s.charAt(b-1)))b--;return s.substring(a,b).replace("\r","");}
    private static final class Lines implements AutoCloseable {
        private final InputStream in;private final long maximum;private long bytes;
        Lines(Path path,boolean gzip,long maximum)throws IOException{InputStream raw=Files.newInputStream(path);this.in=new BufferedInputStream(gzip?new GZIPInputStream(raw):raw);this.maximum=maximum;}
        String next()throws IOException{var row=new ByteArrayOutputStream();int c;while((c=in.read())!=-1){require(++bytes<=maximum,"Complete decoded text exceeds byte capacity");if(c==10)break;require(row.size()<1048576,"Logical line exceeds1MiB capacity");row.write(c);}return c==-1&&row.size()==0?null:utf8(row.toByteArray());}
        @Override public void close()throws IOException{in.close();}
    }
    private static void require(boolean value,String message)throws IOException{if(!value)throw new IOException(message);}
}
